package org.mozilla.geckoview;import org.json.*;public class GeckoSession{public boolean open=true;public int restores,loads;public SessionState last;public String loaded;public boolean isOpen(){return open;}public void restoreState(SessionState value){restores++;last=value;}public void loadUri(String value){loads++;loaded=value;}public static class SessionState{final String value;public SessionState(String v){value=v;}public static SessionState fromString(String v){try{new JSONObject(v);return new SessionState(v);}catch(Exception invalid){return null;}}public int size(){try{return new JSONObject(value).getJSONObject("history").getJSONArray("entries").length();}catch(Exception invalid){return 0;}}public String toString(){return value;}}}
